const crypto = require('crypto');

function header(headers, name) {
  if (!headers) return '';
  const want = String(name).toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (String(k).toLowerCase() === want) return Array.isArray(v) ? String(v[0] || '') : String(v || '');
  }
  return '';
}

function rawBodyOf(item) {
  try {
    const bin = item.binary || {};
    const data = bin.data || bin.payload || {};
    if (data.data) return Buffer.from(data.data, 'base64').toString('utf8');
  } catch (e) {}
  const j = item.json || {};
  if (typeof j.body === 'string') return j.body;
  return '';
}

function verify(secret, id, ts, sigHeader, rawBody) {
  if (!secret || !id || !ts || !sigHeader || !rawBody) return false;
  const n = parseInt(ts, 10);
  if (!Number.isFinite(n)) return false;
  if (Math.abs(Math.floor(Date.now() / 1000) - n) > 300) return false;
  let b64 = String(secret);
  if (b64.startsWith('whsec_')) b64 = b64.slice(6);
  let key;
  try { key = Buffer.from(b64, 'base64'); } catch (e) { return false; }
  const expected = crypto.createHmac('sha256', key).update(id + '.' + ts + '.' + rawBody).digest('base64');
  const parts = String(sigHeader).split(/\s+/);
  for (const part of parts) {
    const sig = part.includes(',') ? part.split(',').slice(1).join(',') : part;
    const a = Buffer.from(expected);
    const b = Buffer.from(String(sig || ''));
    if (a.length === b.length && crypto.timingSafeEqual(a, b)) return true;
  }
  return false;
}

function asMeeting(raw) {
  if (!raw || typeof raw !== 'object') return {};
  if (raw.body && typeof raw.body === 'object' && (raw.body.recording_id || raw.body.title || raw.body.meeting_title)) return raw.body;
  if (raw.recording_id || raw.title || raw.meeting_title || raw.default_summary || raw.transcript) return raw;
  return raw.body && typeof raw.body === 'object' ? raw.body : raw;
}

function transcriptText(list) {
  if (typeof list === 'string') return list.trim();
  if (!Array.isArray(list)) return '';
  return list.map((row) => {
    if (!row) return '';
    if (typeof row === 'string') return row;
    const who = (row.speaker && (row.speaker.display_name || row.speaker.name)) || row.speaker || '';
    const text = String(row.text || row.content || '').trim();
    if (!text) return '';
    return who ? (who + ': ' + text) : text;
  }).filter(Boolean).join('\n');
}

function summaryText(m) {
  const d = m.default_summary || m.summary || {};
  return String(d.markdown_formatted || d.markdown || d.text || (typeof m.summary === 'string' ? m.summary : '') || '').trim();
}

function actionLines(list) {
  if (!Array.isArray(list)) return [];
  return list.map((it) => {
    if (!it) return '';
    if (typeof it === 'string') return it;
    const who = (it.assignee && (it.assignee.name || it.assignee.email)) || '';
    const desc = String(it.description || it.text || it.title || '').trim();
    if (!desc) return '';
    return who ? (who + ' — ' + desc) : desc;
  }).filter(Boolean);
}

function inviteeLines(list) {
  if (!Array.isArray(list)) return [];
  return list.map((p) => {
    if (!p) return '';
    if (typeof p === 'string') return p;
    const name = String(p.name || '').trim();
    const email = String(p.email || '').trim();
    return [name, email].filter(Boolean).join(' ');
  }).filter(Boolean);
}

const item = $input.first();
const raw = item.json || {};
const headers = raw.headers || {};
const meeting = asMeeting(raw);
const recording_id = String(meeting.recording_id || (meeting.recording && meeting.recording.id) || '').trim();
const title = String(meeting.meeting_title || meeting.title || '').trim();
const when = String(meeting.scheduled_start_time || meeting.recording_start_time || meeting.created_at || '').trim();
const url = String(meeting.share_url || meeting.url || '').trim();
const transcript = transcriptText(meeting.transcript);
const summary = summaryText(meeting);
const actions = actionLines(meeting.action_items);
const invitees = inviteeLines(meeting.calendar_invitees);
const webhookId = header(headers, 'webhook-id');
const ts = header(headers, 'webhook-timestamp');
const sig = header(headers, 'webhook-signature');
let body = rawBodyOf(item);
const secret = String(($env && $env.FATHOM_WEBHOOK_SECRET) || process.env.FATHOM_WEBHOOK_SECRET || '');
let ok = verify(secret, webhookId, ts, sig, body);
if (!ok && meeting && typeof meeting === 'object') {
  try { ok = verify(secret, webhookId, ts, sig, JSON.stringify(meeting)); } catch (e) {}
}
if (!ok && raw.body && typeof raw.body === 'object') {
  try { ok = verify(secret, webhookId, ts, sig, JSON.stringify(raw.body)); } catch (e) {}
}
if (!ok) {
  return [];
}
try {
  const store = $getWorkflowStaticData('global');
  store.seen = Array.isArray(store.seen) ? store.seen : [];
  if (webhookId && store.seen.includes(webhookId)) return [];
  if (webhookId) {
    store.seen.push(webhookId);
    if (store.seen.length > 80) store.seen = store.seen.slice(-80);
  }
} catch (e) {}
const has_transcript = Boolean(transcript);
const has_summary = Boolean(summary) || actions.length > 0;
return [{ json: {
  recording_id,
  title,
  when,
  url,
  transcript,
  summary,
  actions,
  invitees,
  need_fetch: Boolean(recording_id) && (!has_transcript || !has_summary)
} }];

const prep = $('Verify signature').item.json;
const out = Object.assign({}, prep);
try {
  const tr = $('Fetch transcript').first().json;
  const list = Array.isArray(tr) ? tr : (tr && (tr.transcript || tr.items)) || [];
  if (Array.isArray(list) && list.length && !out.transcript) {
    out.transcript = list.map((row) => {
      const who = (row.speaker && (row.speaker.display_name || row.speaker.name)) || row.speaker || '';
      const text = String(row.text || '').trim();
      return who ? (who + ': ' + text) : text;
    }).filter(Boolean).join('\n');
  } else if (typeof tr === 'string' && !out.transcript) {
    out.transcript = tr;
  }
} catch (e) {}
try {
  const sm = $('Fetch summary').first().json || {};
  const text = String(sm.markdown_formatted || sm.markdown || sm.summary || sm.text || '').trim();
  if (text && !out.summary) out.summary = text;
} catch (e) {}
return [{ json: out }];

const m = $input.first().json || {};
const title = String(m.title || '').trim() || '(untitled meeting)';
const actions = Array.isArray(m.actions) ? m.actions : [];
const invitees = Array.isArray(m.invitees) ? m.invitees : [];
const summary = String(m.summary || '').trim();
let transcript = String(m.transcript || '').trim();
if (transcript.length > 12000) transcript = transcript.slice(0, 11990) + '…';
const lines = [
  'Turn this finished meeting into a Delivery week plan. save_plan true.',
  'Map names to people in context. Stay inside stage slots and hours_left.',
  'Extra commitments stay held in the reply, not in items.',
  'Do not send WhatsApp, Telegram, or email. Do not hire. Do not Accept.',
  '',
  'Calendar title: ' + title
];
if (m.when) lines.push('When: ' + m.when);
if (m.url) lines.push('Fathom: ' + m.url);
if (invitees.length) {
  lines.push('Invitees:');
  invitees.slice(0, 20).forEach((x) => lines.push('- ' + x));
}
if (actions.length) {
  lines.push('Action items:');
  actions.slice(0, 30).forEach((x) => lines.push('- ' + x));
}
if (summary) {
  lines.push('Summary:');
  lines.push(summary.slice(0, 6000));
}
if (transcript) {
  lines.push('Transcript:');
  lines.push(transcript);
}
const task = lines.join('\n');
return [{ json: {
  task_description: task,
  context_data: {
    channel: 'notes',
    department: 'delivery',
    action: 'plan',
    cannot_send: true,
    cannot_hire: true,
    meeting_title: title,
    recording_id: String(m.recording_id || ''),
    fathom_url: String(m.url || '')
  }
} }];
